from taf.collectors.ttitrace_4g.collector import TtiTrace4GCollector, TtiTraceServer4G
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core.factories.named_factory import NamedComponentFactory, Factory
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BaseTtiTraceServer4GFactory(Factory):
    """
    Base factory for TtiTraceServer tool instances
    """
    _optional_parameters = {"enb_ip", "ttitrace_server_path"}
    _product_class = TtiTraceServer4G


class LocalTtiTraceServer4GFactory(
        Creating("tool_executor", "LocalExecutor"),
        BaseTtiTraceServer4GFactory):
    """
    Factory to create local TtiTraceServer tool instance
    """
    pass


class RemoteTtiTraceServer4GFactory(
        Creating("tool_executor", "SshExecutor"),
        BaseTtiTraceServer4GFactory):
    """
    Factory to create remote TtiTraceServer SSH tool instance
    """
    pass


class TtiTraceServer4GFactorySelector:
    """
    Factory selector that chooses between local and remote TtiTraceServer factories
    based on the presence of 'executor' in configuration.
    """

    def create(self, configuration, existing_arguments):
        """
        Create TtiTraceServer4G instance using appropriate factory.

        :param dict configuration: Configuration dict that may contain 'executor' key
        :param dict existing_arguments: Existing arguments to pass to factory
        :return: TtiTraceServer4G instance
        """
        if "executor" in configuration:
            return RemoteTtiTraceServer4GFactory().create(configuration=configuration,
                                                          existing_arguments=existing_arguments)
        else:
            return LocalTtiTraceServer4GFactory().create(configuration=configuration,
                                                         existing_arguments=existing_arguments)


class BaseTtiTrace4GCollectorFactory(NamedComponentFactory):
    """
    Base factory for TtiTrace4G collectors
    """
    _mandatory_parameters = {"global_cell_id", "tool"}
    _optional_parameters = {"ttitrace_client_path", "file_name"}
    _product_class = TtiTrace4GCollector


class LocalTtiTrace4GCollectorFactory(
        Creating("tool_executor", "LocalExecutor"),
        Creating("file_getter", "LocalFileGetter"),
        BaseTtiTrace4GCollectorFactory):
    """
    Factory to create local TtiTrace4G collectors
    """
    pass


class RemoteTtiTrace4GCollectorFactory(
        Creating("tool_executor", "SshExecutor"),
        Creating("file_getter", "SshFileGetter", "executor"),
        BaseTtiTrace4GCollectorFactory):
    pass


class TtiTrace4GCollectorFactorySelector(Factory):

    def create(self, configuration, existing_arguments):
        if "executor" in configuration:
            return RemoteTtiTrace4GCollectorFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        else:
            return LocalTtiTrace4GCollectorFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)

TtiTraceServer4GFactory = LocalTtiTraceServer4GFactory
TtiTrace4GCollectorFactory = LocalTtiTrace4GCollectorFactory
